cat > packages/simulation/src/zzexplore.test.ts <<'EOF'
import { it } from "vitest";
import { HEADING_COUNT, isNavigable } from "@pirate-sea-race/content";
import { defaultSimulationConfig as config, dockInReach, HEADING_DX, HEADING_DY, HEADING_SCALE, hullIsClear, INTERACT_BUTTON, NOT_DOCKED, sail, tileCentre, AXIS_SCALE } from "./index.js";
it("explore", () => {
  const r = config.ship.dockRadius;
  const input = { buttons: INTERACT_BUTTON, moveX: 0, moveY: -AXIS_SCALE };
  const sides: Record<string, [number, number]> = { E: [1, 0], S: [0, 1], W: [-1, 0], N: [0, -1] };
  for (const dock of config.map.docks) {
    const berth = tileCentre(config, dock.tileX, dock.tileY);
    const open = Object.entries(sides).filter(([, [dx, dy]]) => isNavigable(config.map, dock.tileX + dx, dock.tileY + dy)).map(([k]) => k);
    let total = 0, moored = 0, outside = 0, inside = 0, never = 0, skipped = 0;
    const bad: string[] = [];
    for (let h = 0; h < HEADING_COUNT; h += 8) {
      const ux = HEADING_DX[h]! / HEADING_SCALE, uy = HEADING_DY[h]! / HEADING_SCALE;
      // points into an open side: moving opposite to the side's outward normal
      if (!open.some((k) => sides[k]![0] * ux + sides[k]![1] * uy < -0.01)) continue;
      for (let off = -r; off <= r; off += 32) {
        for (const speed of [0, Math.floor(config.ship.maxSpeed / 2), config.ship.maxSpeed]) {
          const back = r + 3 * 256;
          const sx = Math.round(berth.x - ux * back - uy * off), sy = Math.round(berth.y - uy * back + ux * off);
          if (!hullIsClear(config, sx, sy)) { skipped++; continue; }
          total++;
          let ship = { id: "a", slot: 0, x: sx, y: sy, heading: h, speed, dock: NOT_DOCKED, mooredThrottle: 0 };
          let result = "never";
          for (let s = 0; s < 200; s++) {
            const next = sail(config, ship, input);
            if (next.dock !== NOT_DOCKED) { result = "moored"; break; }
            if (next.speed === 0 && s > 0) {
              const d2 = (next.x - berth.x) ** 2 + (next.y - berth.y) ** 2;
              result = d2 <= r * r ? "aground-inside" : "aground-outside";
              if (result === "aground-outside") bad.push(`h${h} off${off} sp${speed} at ${Math.round(Math.sqrt(d2))}`);
              break;
            }
            ship = next;
          }
          if (result === "moored") moored++; else if (result === "never") never++; else if (result === "aground-inside") inside++; else outside++;
        }
      }
    }
    console.log(dock.id, dock.side, open.join(""), { total, moored, inside, outside, never, skipped }, bad.slice(0, 6).join("; "));
  }
});
EOF
npx vitest run --project unit packages/simulation/src/zzexplore.test.ts 2>&1 | grep -v "^$" | head -40

