import { it } from "vitest";
import { createSeaMap, HEADING_COUNT, isNavigable, type SeaMapSource } from "@pirate-sea-race/content";
import { defaultSimulationConfig as base, dockInReach, HEADING_DX, HEADING_DY, HEADING_SCALE, hullIsClear, INTERACT_BUTTON, NOT_DOCKED, sail, tileCentre, AXIS_SCALE, type SimulationConfig } from "./index.js";
function testConfig(rows: string[]): SimulationConfig {
  const source: SeaMapSource = { name: "t", widthTiles: rows[0]!.length, heightTiles: rows.length, rows,
    islands: [{ name: "Test Isle", theme: "tropical", tileX: 0, tileY: 0, widthTiles: rows[0]!.length, heightTiles: rows.length }],
    spawnSlots: [{ tileX: 1, tileY: 1, facing: "E" }], hub: { tileX: 1, tileY: 1 } };
  const map = createSeaMap(source);
  return { ...base, map, spawnSlots: map.spawnSlots };
}
const pier = Array.from({ length: 15 }, (_, y) => (y === 7 ? "........D######" : "..............."));
const coast = Array.from({ length: 12 }, (_, y) => (y < 3 ? "###############" : y === 3 ? "#######D#######" : "..............."));
const harbour = ["............", "............", "............", "....#####...", "....##D.....", "............", "............", "............", "............"];
for (const [name, rows] of [["pier", pier], ["coast", coast], ["harbour", harbour]] as const) it(name, () => {
  const config = testConfig(rows as string[]);
  const r = config.ship.dockRadius;
  const input = { buttons: INTERACT_BUTTON, moveX: 0, moveY: -AXIS_SCALE };
  const sides: Record<string, [number, number]> = { E: [1, 0], S: [0, 1], W: [-1, 0], N: [0, -1] };
  const dock = config.map.docks[0]!;
  const berth = tileCentre(config, dock.tileX, dock.tileY);
  const open = Object.entries(sides).filter(([, [dx, dy]]) => isNavigable(config.map, dock.tileX + dx, dock.tileY + dy)).map(([k]) => k);
  const tally: Record<string, number> = {};
  const bad: string[] = [];
  for (let h = 0; h < HEADING_COUNT; h += 8) {
    const ux = HEADING_DX[h]! / HEADING_SCALE, uy = HEADING_DY[h]! / HEADING_SCALE;
    if (!open.some((k) => sides[k]![0] * ux + sides[k]![1] * uy < -0.01)) continue;
    for (let off = -r; off <= r; off += 32) {
      for (const speed of [0, Math.floor(config.ship.maxSpeed / 2), config.ship.maxSpeed]) {
        const back = r + 2 * 256;
        const sx = Math.round(berth.x - ux * back - uy * off), sy = Math.round(berth.y - uy * back + ux * off);
        let result = "never";
        if (!hullIsClear(config, sx, sy)) result = "skipped";
        let ship = { id: "a", slot: 0, x: sx, y: sy, heading: h, speed, dock: NOT_DOCKED, mooredThrottle: 0 };
        for (let s = 0; s < 200 && result === "never"; s++) {
          const next = sail(config, ship, input);
          if (next.dock !== NOT_DOCKED) { result = "moored"; break; }
          if (next.speed === 0 && s > 0) {
            const d2 = (next.x - berth.x) ** 2 + (next.y - berth.y) ** 2;
            result = d2 <= r * r ? "aground-inside" : "aground-outside";
            if (result !== "moored") bad.push(`${result} h${h} off${off} sp${speed} at ${Math.round(Math.sqrt(d2))}`);
          }
          ship = next;
        }
        tally[result] = (tally[result] ?? 0) + 1;
      }
    }
  }
  console.log(name, open.join(""), tally, "\n" + bad.filter((_, i) => i % 3 === 0).join("\n"));
});
