import { matchMaker } from "colyseus";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
import { seaMap, SIGHT_RADIUS_TILES, SUB_UNITS_PER_TILE } from "@pirate-sea-race/content";
import { defaultSimulationConfig, hullPathIsClear, tileCentre } from "@pirate-sea-race/simulation";
import { MatchRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
import { AHEAD, HeadlessClient, sleep, type ShipView } from "@pirate-sea-race/test-tools";

/**
 * Server-enforced visibility (§3, §16) on real clients: what each headless client decodes, and the raw bytes it
 * received, hold its own ship and the ships inside its sight radius, and nothing else.
 */
let server: RunningGameServer;
let endpoint: string;
const clients: HeadlessClient[] = [];
const SIGHT = SIGHT_RADIUS_TILES * SUB_UNITS_PER_TILE;
/** The row three tiles south of the hub, which the map keeps clear for 20 tiles either side of the hub. */
const OPEN_ROW = seaMap.hub.tileY + 3;
const HUB_X = seaMap.hub.tileX;

async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
    expect(room.viewedShipIds(guest.sessionId)).toEqual([guest.sessionId]);

    // The guest sails toward the host. Until the host is in its state, it is out of range; once it is, it is in range.
    let wasHidden = false;
    await guest.holdUntil(AHEAD, () => {
      const ownShip = guest.ship()!;
      const seen = guest.ship(host.sessionId);
      if (seen === undefined) {
        expect(distance(ownShip, hostShip)).toBeGreaterThan(SIGHT - 3 * 64);
        wasHidden = true;
        return false;
      }
      expect(distance(ownShip, seen)).toBeLessThanOrEqual(SIGHT);
      return true;
    });
    expect(wasHidden).toBe(true);
describe("keyboard axes", () => {
  it("makes opposing keys neutral", () => {
    expect(axis(true, true)).toBe(0);
    expect(axis(true, false)).toBe(-1);
    expect(axis(false, true)).toBe(1);
    expect(axis(false, false)).toBe(0);
  });
});

describe("sea keyboard", () => {
  it("keeps a tap of E that goes down and up between two reads, reports it once, and that tap docks", () => {
    const keyboard = new KeyboardHelm(new EventTarget() as unknown as Window);
    expect(keyboard.helm()).toEqual({ moveX: 0, moveY: 0, buttons: 0 });
    // Down and up before the page's next read (every 16.7 ms).
    keyboard.press("KeyE");
    keyboard.release("KeyE");
    const tapped = keyboard.helm();
    expect(tapped).toEqual({ moveX: 0, moveY: 0, buttons: Buttons.Interact });
    expect(keyboard.helm().buttons).toBe(0);
    // A held E stays in on every read until it is released; arrows are only what is held.
    keyboard.press("KeyE");
    keyboard.press("ArrowUp");
    expect(keyboard.helm()).toEqual({ moveX: 0, moveY: -1, buttons: Buttons.Interact });
    expect(keyboard.helm()).toEqual({ moveX: 0, moveY: -1, buttons: Buttons.Interact });
    keyboard.release("KeyE");
    keyboard.release("ArrowUp");
    expect(keyboard.helm()).toEqual({ moveX: 0, moveY: 0, buttons: 0 });

    // The tap goes out as one input message, and the server's step moors a slow ship beside a dock with it.
    const sent: InputMessage[] = [];
    const sender = new InputSender({ send: (type, message) => type === MessageType.Input && sent.push(message) });
    sender.update(tapped, 0);
    sender.update(keyboard.helm(), 17);
    expect(sent.map((message) => message.buttons)).toEqual([Buttons.Interact, 0]);
    const config = defaultSimulationConfig;
    const dock = config.map.docks[0]!;
    const berth = tileCentre(config, dock.tileX, dock.tileY);
    const ship: ShipState = { id: "a", slot: 0, x: berth.x + 1, y: berth.y, heading: 0, speed: 0, dock: NOT_DOCKED, mooredThrottle: 0 };
    const [message] = sent;
    const moored = sail(config, ship, { buttons: message!.buttons, moveX: quantizeAxis(message!.moveX), moveY: quantizeAxis(message!.moveY) });
    expect(moored).toMatchObject({ ...berth, speed: 0, dock: dock.id });
  });
});
